// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title 15market Treasury
 * @dev Authoritative prediction market contract. The CONTRACT decides win/loss
 *      on-chain by comparing the settled exit price against the stored entry price.
 *
 * Lifecycle:
 *   1. placeBet()  — user stakes USDC and the entry price/direction are stored on-chain.
 *   2. settleBet() — backend supplies the exit price; the contract determines `won`
 *                    itself and pays the backend-provided dynamic payout amount.
 *
 * The backend cannot mark a trade wrong: the win/loss decision lives on-chain.
 * The backend only supplies the exit price (its price oracle) and the off-chain
 * computed payout amount (dynamic share pricing).
 */
abstract contract Ownable {
    address public owner;
    constructor() { owner = msg.sender; }
    modifier onlyOwner() { require(msg.sender == owner, "Not owner"); _; }
    function transferOwnership(address newOwner) external onlyOwner { owner = newOwner; }
}

contract ArcPrediction is Ownable {
    struct Bet {
        uint256 id;
        address user;
        uint256 amount;
        uint8 direction;       // 0: UP, 1: DOWN
        uint256 entryPrice;
        uint256 duration;
        uint256 timestamp;
        uint8 marketId;
        address payoutAddress;
        uint256 settlementPrice;
        bool settled;
        bool won;
    }

    mapping(uint256 => Bet) public bets;
    uint256 public totalVolume;

    event BetPlaced(uint256 indexed id, address indexed user, uint256 amount, uint8 direction, uint256 entryPrice, uint256 duration, uint256 timestamp, uint8 marketId);
    event BetSettled(uint256 indexed id, address indexed user, uint256 settlementPrice, bool won, uint256 payout);

    receive() external payable {}

    /**
     * @dev Place a bet. User sends stake to contract.
     * @param _betId      Unique trade ID (generated by backend)
     * @param _direction  0 = UP, 1 = DOWN
     * @param _duration   Trade duration in seconds
     * @param _entryPrice Entry price (8 decimals)
     * @param _marketId   Market identifier
     * @param _payoutAddress Wallet to receive winnings
     */
    function placeBet(
        uint256 _betId,
        uint8 _direction,
        uint256 _duration,
        uint256 _entryPrice,
        uint8 _marketId,
        address _payoutAddress
    ) external payable {
        require(msg.value > 0, "No stake");
        require(bets[_betId].id == 0, "ID exists");

        bets[_betId] = Bet({
            id: _betId,
            user: msg.sender,
            amount: msg.value,
            direction: _direction,
            entryPrice: _entryPrice,
            duration: _duration,
            timestamp: block.timestamp,
            marketId: _marketId,
            payoutAddress: _payoutAddress,
            settlementPrice: 0,
            settled: false,
            won: false
        });

        totalVolume += msg.value;
        emit BetPlaced(_betId, msg.sender, msg.value, _direction, _entryPrice, _duration, block.timestamp, _marketId);
    }

    /**
     * @dev Settle a bet. Authority restricted to Owner (Backend).
     *      The CONTRACT determines the result on-chain by comparing the exit
     *      price against the stored entry price, then transfers the
     *      backend-provided payout amount from the Treasury to the payoutAddress.
     *
     *      A tie (exit == entry) is a PUSH: the original stake is refunded.
     */
    function settleBet(uint256 _betId, uint256 _exitPrice, uint256 _payoutAmount) external onlyOwner {
        Bet storage bet = bets[_betId];
        require(bet.id != 0, "Bet not found");
        require(!bet.settled, "Already settled");

        bet.settlementPrice = _exitPrice;
        bet.settled = true;

        uint256 payout = 0;

        if (_exitPrice == bet.entryPrice) {
            // PUSH — refund the original stake, no winner.
            bet.won = false;
            payout = bet.amount;
            require(address(this).balance >= payout, "Insufficient Treasury funds");
            (bool refunded, ) = payable(bet.payoutAddress).call{value: payout}("");
            require(refunded, "Refund transfer failed");
        } else {
            // Contract-authoritative result: 0 = UP, 1 = DOWN.
            if (bet.direction == 0) {
                bet.won = (_exitPrice > bet.entryPrice);
            } else {
                bet.won = (_exitPrice < bet.entryPrice);
            }

            if (bet.won) {
                // Payout is calculated authoritatively off-chain based on real-time
                // share prices and passed in by the backend oracle.
                payout = _payoutAmount;
                require(address(this).balance >= payout, "Insufficient Treasury funds");
                (bool success, ) = payable(bet.payoutAddress).call{value: payout}("");
                require(success, "Payout transfer failed");
            }
        }

        emit BetSettled(_betId, bet.user, _exitPrice, bet.won, payout);
    }

    /**
     * @dev Emergency payout fallback.
     */
    function manualPayout(address payable _to, uint256 _amount) external onlyOwner {
        require(address(this).balance >= _amount, "Insufficient funds");
        (bool success, ) = _to.call{value: _amount}("");
        require(success, "Transfer failed");
    }

    /**
     * @dev Protocol revenue withdrawal.
     */
    function withdraw(uint256 _amount) external onlyOwner {
        require(address(this).balance >= _amount, "Insufficient funds");
        (bool success, ) = payable(owner).call{value: _amount}("");
        require(success, "Withdraw failed");
    }
}

